  width: 100%;
  padding: 12px 16px;
  font-size: 16px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  color: var(--text-h);
  box-sizing: border-box;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.form-group input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-bg);
}

.error-message {
  display: block;
  color: #ef4444;
  font-size: 13px;
  margin-top: 6px;
}

.btn-group {
  display: flex;
  gap: 12px;
  margin-top: 32px;
  justify-content: flex-end;
}

.btn {
  padding: 12px 24px;
  font-size: 16px;
  font-weight: 500;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s ease, opacity 0.2s ease;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
}

.btn-primary:hover:not(:disabled) {
  opacity: 0.9;
}

.btn-secondary {
  background: var(--border);
  color: var(--text-h);
}

.btn-secondary:hover:not(:disabled) {
  opacity: 0.9;
}

.btn-success {
  background: #10b981;
  color: #fff;
}

.btn-success:hover:not(:disabled) {
  background: #059669;
}

/* Success Message styles */
.success-container {
  background: var(--code-bg);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 40px;
  text-align: center;
  box-shadow: var(--shadow);
}

.success-container h2 {
  color: #10b981;
  margin-bottom: 16px;
}

.success-container p {
  font-size: 16px;
  margin-bottom: 24px;
}

.data-box {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 20px;
  margin-bottom: 24px;
  text-align: left;
}

.data-box p {
  margin: 8px 0;
  font-size: 15px;
}

.success-container pre {
  background: var(--bg);
  border: 1px solid var(--border);
  padding: 16px;
  border-radius: 6px;
  text-align: left;
  overflow-x: REDACTED;
  font-family: var(--mono);
  font-size: 14px;
  margin-bottom: 24px;
}

